ers[j]=null;a.monsters[i].atk+=200;log('Claimant survives battle and gains 200 ATK.')}}else if(c.id==='claim'){const slot=getEmptyMon(p);if(slot>=0){p.monsters[slot]={...c,owner:'player',attacked:true};a.monsters[i]=null;p.monsters[j].atk+=200;log('Claimant effect: you take Astra’s attacker; Claimant gains 200 ATK.')}else{a.grave.push(c);a.monsters[i]=null;p.monsters[j].atk+=200}}else if(c.atk>defender.atk){a.grave.push(defender);p.monsters[j]=null;p.lp=Math.max(0,p.lp-(c.atk-defender.atk));log(`${c.name} destroys ${defender.name}. You take ${c.atk-defender.atk} damage.`)}else if(c.atk<defender.atk){a.grave.push(c);a.monsters[i]=null;a.lp=Math.max(0,a.lp-(defender.atk-c.atk));log(`${defender.name} defeats ${c.name}. Astra takes ${defender.atk-c.atk} damage.`)}else{a.grave.push(c);p.grave.push(defender);a.monsters[i]=null;p.monsters[j]=null;log('Equal ATK! Both monsters are destroyed.')}}else{let trapIndex=p.back.findIndex(x=>x&&x.faceDown&&x.kind==='trap');if(trapIndex>=0){const t=p.back[trapIndex];p.back[trapIndex]=null;p.grave.push(t);if(t.id==='ambush'){a.grave.push(c);a.monsters[i]=null;log('Amber Ambush destroys Astra’s attacker!')}else{log('Mirror Guard negates the attack!');continue}}else{p.lp=Math.max(0,p.lp-c.atk);log(`${c.name} attacks directly for ${c.atk} damage.`)}}render();checkWin();if(state.gameOver)return}setTimeout(()=>{if(state.gameOver)return;a.normalUsed=false;a.attacked.clear();state.whose='player';state.turnOwner='player';state.turn++;state.phase=0;selected=null;draw('player',true);state.phase=2;log(`Turn ${state.turn}: your Draw and Main Phases begin.`);render()},420)},550)}
function summonFusion(){if(!legalPlayer())return;const p=state.player;if(!p.extra)return toast('Your Extra Deck is empty.');const bodies=p.monsters.map((x,i)=>x&&i<4?i:-1).filter(i=>i>=0);if(bodies.length<2)return toast('Fusion needs two monsters on your field.');const ix=bodies.slice(0,2);showModal('Fusion summon','Send two of your monsters to the Graveyard to Fusion Summon Twin Fang Chimera (3000 ATK / 2400 DEF)?','FUSION SUMMON','CANCEL',()=>{for(const i of ix){p.grave.push(p.monsters[i]);p.monsters[i]=null}const f={...p.extra,owner:'player',attackReady:true};p.extra=null;p.monsters[4]=f;log('Twinfang Chimera is Fusion Summoned!');selected=null;render()})}
