let onlineSocket=null,onlineRooms=[],onlineRoomId=null,onlineRole=null;
function connectOnline(){
  if(onlineSocket&&onlineSocket.readyState<=1)return;
  const proto=location.protocol==='https:'?'wss':'ws';
  onlineSocket=new WebSocket(`${proto}://${location.host}`);
  onlineSocket.onopen=()=>{onlineSocket.send(JSON.stringify({type:'name',name:$('playerInput').value.trim()||'Duelist'}));onlineSocket.send(JSON.stringify({type:'list'}))};
  onlineSocket.onmessage=e=>{let m;try{m=JSON.parse(e.data)}catch{return}
    if(m.type==='rooms'){onlineRooms=m.rooms||[];refreshRoomList()}
    if(m.type==='joined'){onlineRoomId=m.roomId;onlineRole=m.role;showWaitingRoom()}
    if(m.type==='room-update'){refreshWaitingRoom(m.room)}
    if(m.type==='chat'){appendOnlineChat(m.name,m.text)}
    if(m.type==='error')toast(m.message)
  };
  onlineSocket.onclose=()=>{onlineRooms=[];onlineRoomId=null;onlineRole=null};
}
function refreshRoomList(){
  const el=$('roomListItems');if(!el)return;
  el.innerHTML=onlineRooms.length?onlineRooms.map(r=>`<div class="room-row"><div><strong>${escapeHtml(r.name)}</strong><br><small>HOST / ${escapeHtml(r.host)} · ${r.format} LP</small></div><small>${r.players}/2 · ${r.status.toUpper}</small><button data-room-id="${r.id}" ${r.players>=2?'disabled':''}>JOIN</button></div>`).join(''):'<div class="room-empty">No live rooms yet. Create the first one.</div>';
  el.querySelectorAll('[data-room-id]').forEach(b=>b.onclick=()=>joinOnlineRoom(b.dataset.roomId));
}
function openRoomList(){connectOnline();
  modalHtml('LIVE ROOM LIST',`<div class="online-create"><input id="onlineRoomName" maxlength="22" value="${escapeHtml($('roomInput').value.trim()||'Skyline Room')}"><select id="onlineFormat"><option value="8000">8000 LP</option><option value="4000">4000 LP</option></select><button id="createOnlineRoom">CREATE ROOM</button></div><div class="room-status"><i></i><span id="onlineStatus">CONNECTING…</span></div><div class="room-list" id="roomListItems"><div class="room-empty">Searching live rooms…</div></div>`,[{text:'CLOSE',class:'secondary-btn'}]);
  setTimeout(()=>{const st=$('onlineStatus');if(st)st.textContent=onlineSocket?.readyState===1?'CONNECTED':'CONNECTING…';refreshRoomList()},300);
  $('createOnlineRoom').onclick=()=>{if(!onlineSocket||onlineSocket.readyState!==1)return toast('Server is connecting. Try again.');onlineSocket.send(JSON.stringify({type:'name',name:$('playerInput').value.trim()||'Duelist'}));onlineSocket.send(JSON.stringify({type:'create',name:$('onlineRoomName').value,format:Number($('onlineFormat').value)}))};
}
function joinOnlineRoom(id){if(!onlineSocket||onlineSocket.readyState!==1)return toast('Server is connecting.');onlineSocket.send(JSON.stringify({type:'name',name:$('playerInput').value.trim()||'Duelist'}));onlineSocket.send(JSON.stringify({type:'join',roomId:id}))}
function showWaitingRoom(){
  modalHtml('ONLINE DUEL ROOM',`<div class="room-status"><i></i><span id="waitingStatus">WAITING FOR DUELIST</span></div><div class="room-list" id="waitingPlayers"><div class="room-empty">Joining room…</div></div><div class="modal-actions"><button class="secondary-btn" id="onlineReadyBtn">READY</button><button class="secondary-btn" id="onlineLeaveBtn">LEAVE ROOM</button></div><div class="chat" id="onlineChatLines" style="margin-top:12px"><div class="chat-line"><strong>SYSTEM</strong> Room chat is live.</div></div><form class="chat-form" id="onlineChatForm"><input id="onlineChatInput" maxlength="240" placeholder="Message room…"><button>SEND</button></form>`,[{text:'CLOSE',class:'secondary-btn',run:()=>leaveOnlineRoom()}]);
  $('onlineReadyBtn').onclick=()=>{onlineSocket?.send(JSON.stringify({type:'ready',ready:true}))};$('onlineLeaveBtn').onclick=leaveOnlineRoom;$('onlineChatForm').onsubmit=e=>{e.preventDefault();const i=$('onlineChatInput');if(i?.value.trim())onlineSocket?.send(JSON.stringify({type:'chat',text:i.value.trim()}));if(i)i.value=''};
}
function refreshWaitingRoom(room){if(!$('waitingPlayers'))return;const phtml=room.players.map(p=>`<div class="room-row"><div><strong>${escapeHtml(p.name)}</strong><br><small>${p.ready?'READY':'NOT READY'}</small></div><small>${p.id===onlineRoomId?'':'DUELIST'}</small></div>`).join('');$('waitingPlayers').innerHTML=phtml||'<div class="room-empty">Waiting…</div>';const status=$('waitingStatus');if(status)status.textContent=room.status==='ready'?'MATCH READY — BOTH DUELISTS':'WAITING FOR DUELIST';if(room.status==='ready')toast('Both duelists are ready. Online duel controls will sync in this room.')}
function appendOnlineChat(name,text){const el=$('onlineChatLines');if(!el)return;el.innerHTML+=`<div class="chat-line"><strong>${escapeHtml(name).toUpper()}</strong> ${escapeHtml(text)}</div>`;el.scrollTop=el.scrollHeight}
function leaveOnlineRoom(){if(onlineSocket&&onlineSocket.readyState===1)onlineSocket.send(JSON.stringify({type:'leave'}));onlineRoomId=null;onlineRole=null;$('overlayRoot').innerHTML='' }
$('openRoomList').onclick=openRoomList;
$('startDuel').onclick=init;

